python3 - "$R" <<'EOF'
import sys,os,base64,hashlib,csv
R=sys.argv[1]; SP=os.path.join(R,'site-packages')
def h(p):
    return base64.urlsafe_b64encode(hashlib.sha256(open(p,'rb').read()).digest()).rstrip(b'=').decode()
for d in sorted(os.listdir(SP)):
    if not d.endswith('.dist-info'): continue
    rec=os.path.join(SP,d,'RECORD')
    issues=[]
    listed=set()
    for row in csv.reader(open(rec)):
        if not row: continue
        path,hs,sz=row[0],row[1],row[2] if len(row)>2 else ''
        listed.add(path)
        full=os.path.join(SP,path)
        if not os.path.exists(full):
            issues.append(f'MISSING {path}'); continue
        if hs.startswith('sha256='):
            if h(full)!=hs.split('=',1)[1]:
                issues.append(f'HASHMISMATCH {path}')
    # find on-disk files not in RECORD for that dist's top-levels
    tl=os.path.join(SP,d,'top_level.txt')
    tops=[l.strip() for l in open(tl)] if os.path.exists(tl) else []
    for t in tops:
        base=os.path.join(SP,t)
        if os.path.isdir(base):
            for root,_,fs in os.walk(base):
                for f in fs:
                    rel=os.path.relpath(os.path.join(root,f),SP)
                    if rel not in listed: issues.append(f'UNRECORDED {rel}')
        elif os.path.exists(base+'.py'):
            rel=t+'.py'
            if rel not in listed: issues.append(f'UNRECORDED {rel}')
    if issues: print(d, '->', '; '.join(issues))
EOF
